#include "reference_audio_fixtures.hpp"
#include <algorithm>
#include <iostream>
#include <stdexcept>
using namespace fathom;
using namespace reference_fixtures;
static int checks=0;
static void check(bool ok,const char* name){++checks;if(!ok)throw std::runtime_error(name);std::cout<<"PASS "<<name<<'\n';}
static music::RendererCapabilities capabilities(bool poly=false){music::RendererCapabilities c{{music::Attack::Picked,music::Attack::Held,music::Attack::HammerOn,music::Attack::PullOff},false,true,true};c.polyphonicHeldChains=poly;return c;}
static std::size_t issues(const music::Readiness& r,const char* code){return std::count_if(r.issues.begin(),r.issues.end(),[&](const music::Issue& i){return i.code==code;});}
static bool compiles(const music::Model& m,reference::Configuration cfg=config(Rational{4})){try{(void)reference::compile(checked(m),cfg);return true;}catch(const std::exception& e){std::cout<<"REFUSAL "<<e.what()<<'\n';return false;}}
static music::Model chordChain(bool heldChord){auto m=chord(false);m.events.pop_back();m.events[0].tones.resize(2);auto e=m.events[0];e.id="held-1";e.span={Rational{2},Rational{1}};e.kind=heldChord?music::Kind::Chord:music::Kind::Note;if(!heldChord)e.tones.resize(1);for(auto& t:e.tones){t.attack=music::Attack::Held;t.tieFrom=m.events[0].id;t.memberSpan=heldChord?std::optional<music::Span>{e.span}:std::optional<music::Span>{};}m.events.push_back(e);return m;}
int main(){try{
 auto picked=chord(false);auto p=music::validate(picked);check(p.validReference(),"picked chord source valid");auto pr=music::assessReadiness(*p.model,capabilities());check(pr.technicallyRenderable&&issues(pr,"unsupported_held_chord")==0,"picked chord ready without held issue");check(!pr.curriculumPlaybackAuthorized,"technical readiness not curriculum admission");check(compiles(picked,config(Rational{5,2})),"picked chord compiles");
 auto single=held();auto s=music::validate(single);check(s.validReference(),"single picked-held source valid");check(music::assessReadiness(*s.model,capabilities()).technicallyRenderable,"single picked-held ready");check(compiles(single),"single picked-held compiles");
 for(bool chordHeld:{true,false}){auto m=chordChain(chordHeld);auto v=music::validate(m);check(v.validReference(),"chord origin model remains source valid");auto r=music::assessReadiness(*v.model,capabilities());check(!r.technicallyRenderable&&issues(r,"unsupported_held_chord")==1,"one unsupported issue per held event");check(r.issues.front().event=="held-1"&&r.issues.front().field=="tieFrom"&&r.issues.back().code=="not_admitted","issue order and admission tail stable");check(!compiles(m),"current renderer refuses chord held structure");auto declared=music::assessReadiness(*v.model,capabilities(true));check(declared.technicallyRenderable&&issues(declared,"unsupported_held_chord")==0,"explicit generic polyphonic capability permits readiness");check(!declared.curriculumPlaybackAuthorized&&!compiles(m),"generic capability does not change current renderer or admission");}
 auto repeated=chordChain(true);auto next=repeated.events.back();next.id="held-2";next.span={Rational{3},Rational{1}};for(auto& t:next.tones){t.tieFrom="held-1";t.memberSpan=next.span;}repeated.events.push_back(next);auto rv=music::validate(repeated);check(rv.validReference(),"two held chord events source valid");auto rr=music::assessReadiness(*rv.model,capabilities());check(issues(rr,"unsupported_held_chord")==2&&rr.issues[0].event=="held-1"&&rr.issues[1].event=="held-2","one held issue per event in source order");
 auto broken=chordChain(false);broken.events.back().tones[0].tieFrom="absent";auto b=music::validate(broken);check(!b.validReference()&&!b.model,"missing origin remains invalid source");check(std::any_of(b.issues.begin(),b.issues.end(),[](const auto& i){return i.code=="tie_identity";}),"missing origin reports tie identity");
 for(auto attack:{music::Attack::HammerOn,music::Attack::PullOff}){auto m=synthetic("nonpicked-held");int first=attack==music::Attack::HammerOn?5:7,second=attack==music::Attack::HammerOn?7:5;m.events={note("picked",Rational{},Rational{1},3,first,50+first),note("arrival",Rational{1},Rational{1},3,second,50+second),note("held",Rational{2},Rational{1},3,second,50+second)};m.events[1].tones[0].attack=attack;m.events[2].tones[0].attack=music::Attack::Held;m.events[2].tones[0].tieFrom="arrival";auto v=music::validate(m);check(v.validReference(),"nonpicked held source valid");check(music::assessReadiness(*v.model,capabilities()).technicallyRenderable,"nonpicked held ready");check(compiles(m),"nonpicked held compiles");}
 check(!compiles(picked,config(Rational{1})),"ready picked chord refuses short cycle");check(!compiles(picked,config(Rational{5,2},1000)),"ready picked chord refuses low sample rate");
 std::cout<<"CHECKS "<<checks<<" PASS\n";return 0;
 }catch(const std::exception& e){std::cerr<<"FAIL after "<<checks<<": "<<e.what()<<'\n';return 1;}}
